// apps/tap-flip/src/rules/scramble.ts
import { nextInt } from '@e07/game-kit/rng/sfc32.ts';

import type { RngDraw, RngState } from '@e07/game-kit/rng/sfc32.ts';

/** One seeded cell: create() calls it, and so does apply-move (a draw during play). */
export function drawCell(rng: RngState, size: number): RngDraw {
  return nextInt(rng, size);
}

